import time, random
from concurrent.futures import ThreadPoolExecutor, as_completed

class QuorumStore:
    def __init__(self, nodes, quorum=2, timeout_ms=300):
        self.nodes = nodes  # each has append(entry)->bool with fsync
        self.quorum = quorum
        self.timeout = timeout_ms / 1000.0

    def commit(self, entry) -> bool:
        # entry carries (term, index, idempotency_key). Retries are safe.
        acks = 1  # leader local append already done
        with ThreadPoolExecutor(max_workers=len(self.nodes)) as pool:
            futs = {pool.submit(n.append, entry): n for n in self.nodes}
            deadline = time.time() + self.timeout
            for f in as_completed(futs, timeout=self.timeout):
                try:
                    if f.result(timeout=max(0, deadline - time.time())):
                        acks += 1
                        if acks >= self.quorum:
                            return True  # commit point
                except Exception:
                    continue  # timeout / crash = no vote, never retry blindly
        return False  # do NOT apply, do NOT ack client as durable
